
const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
function planKey(d,s){return d+'|'+s}
function renderPlanner(){let r=document.querySelector('[data-planner]');if(!r)return;let plan=NF.getPlan();let recipes=[...document.querySelectorAll('[data-recipe-choice]')].map(x=>({id:x.dataset.id,name:x.dataset.name,protein:x.dataset.protein}));r.innerHTML=days.map(d=>`<div class="day-plan"><h3>${d}</h3>${['Lunch','Dinner'].map(s=>{let x=plan[planKey(d,s)];return `<div class="meal-slot"><span><b>${s}</b><br><small>${x?x.name:'Nothing planned yet'}</small></span><select data-slot="${planKey(d,s)}"><option value="">Choose…</option>${recipes.map(q=>`<option value="${q.id}" ${x&&x.id===q.id?'selected':''}>${q.name}</option>`).join('')}</select></div>`}).join('')}</div>`).join('');r.querySelectorAll('select').forEach(s=>s.onchange=()=>{let recipe=recipes.find(x=>x.id===s.value);if(recipe)plan[s.dataset.slot]=recipe;else delete plan[s.dataset.slot];NF.setPlan(plan);renderShopping()})}
function renderShopping(){let el=document.querySelector('[data-shopping-from-plan]');if(!el)return;let plan=NF.getPlan(),vals=Object.values(plan);if(!vals.length){el.innerHTML='<p>No meals planned yet. Add meals in the meal planner first.</p>';return}let counts={};vals.forEach(x=>counts[x.name]=(counts[x.name]||0)+1);el.innerHTML=Object.entries(counts).map(([n,c])=>`<label><input type="checkbox"> ${c} × ${n} ingredients</label>`).join('')}
document.addEventListener('DOMContentLoaded',()=>{renderPlanner();renderShopping()});
